#include "DiamondTrap.hpp"

int main()
{
    {
        DiamondTrap diamond("Diomand Class");

        std::cout << diamond.getName() << " has " << diamond.getHitPoints()
            << " hit points, " << diamond.getEnergyPoints()
            << " energy points and " << diamond.getAttackDamage()
            << " attack damage." << std::endl;

        diamond.whoAmI();
        diamond.attack("training dummy");
        diamond.guardGate();
        diamond.highFivesGuys();
        diamond.takeDamage(40);
        diamond.beRepaired(20);

        DiamondTrap copy(diamond);
        copy.whoAmI();
        copy = diamond;
    }

    return 0;
}
